var _getViewIdChain = $ax.style.getViewIdChain = function(currentViewId, id, diagramObject) {
    var viewIdChain;
    if (diagramObject.owner.type == 'Axure:Master' || diagramObject.owner.type == 'referenceDiagramObject') {
